var MAIL_ROLE=['admin','administrator','info','support','sales','billing','noreply','no-reply','hello','contact','help','postmaster','abuse','root','webmaster','office','team','mail','newsletter','marketing'];
function mailValidate(email){
  if(typeof email!=='string') return {valid:false, error:'not string'};
  email=email.trim();
  if(email.length===0) return {valid:false, error:'empty'};
  if(email.length>254) return {valid:false, error:'too long'};
  var at=email.lastIndexOf('@');
  if(at<1 || at===email.length-1) return {valid:false, error:'missing @'};
  var local=email.slice(0,at), domain=email.slice(at+1);
  if(local.length>64) return {valid:false, error:'local too long'};
  if(!/^[A-Za-z0-9.!#$%&'*+\/=?^_`{|}~-]+$/.test(local)) return {valid:false, error:'local invalid chars'};
  if(!/^[A-Za-z0-9.-]+$/.test(domain)) return {valid:false, error:'domain invalid chars'};
  if(domain.indexOf('..')>=0) return {valid:false, error:'domain has ..'};
  if(domain.indexOf('.')<0) return {valid:false, error:'domain missing dot'};
  var tld=domain.split('.').pop();
  if(tld.length<2) return {valid:false, error:'tld too short'};
  return {valid:true, local:local, domain:domain, tld:tld, error:null};
}
function mailParse(email){
  var r=mailValidate(email);
  if(!r.valid) return {valid:false, error:r.error};
  var plus=r.local.indexOf('+');
  var tag = plus>=0 ? r.local.slice(plus+1) : null;
  var baseLocal = plus>=0 ? r.local.slice(0,plus) : r.local;
  return {valid:true, local:r.local, baseLocal:baseLocal, tag:tag, domain:r.domain, tld:r.tld, isTagged: tag!==null, error:null};
}
function mailRole(email){
  var r=mailValidate(email);
  if(!r.valid) return {valid:false, error:r.error, role:null, type:null};
  var local=r.local.toLowerCase();
  if(MAIL_ROLE.indexOf(local)>=0) return {valid:true, role:true, type:'role', local:local};
  if(local.indexOf('no')===0 && /reply/.test(local)) return {valid:true, role:true, type:'role', local:local};
  return {valid:true, role:false, type:'personal', local:local};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { validate:mailValidate, parse:mailParse, role:mailRole };
}
if (typeof window !== 'undefined') {
  window.MailForgePure = { validate:mailValidate, parse:mailParse, role:mailRole };
}
